    "ezconvolution": { minArgs: 3, maxArgs: 5, signature: "ezconvolution(tensor, size_x, kernel) / ezconvolution(tensor, size_x, size_y, kernel) / ezconvolution(tensor, size_x, size_y, size_z, kernel)", forms: [["tensor", "size_x", "kernel"], ["tensor", "size_x", "size_y", "kernel"], ["tensor", "size_x", "size_y", "size_z", "kernel"]], description: "convolves tensor with a 1D, 2D or 3D kernel, guessing whether channels come first or last. kernel is evaluated over the kernel grid with kx/ky/kz coordinates", details: "", params: {"tensor": "input, channels first or last", "size_x": "kernel size along the first spatial dimension", "kernel": "expression for the kernel weights, evaluated over the kernel grid with kx/ky/kz offsets from its centre", "size_y": "kernel size along the second spatial dimension", "size_z": "kernel size along the third spatial dimension"}, aliases: ["ezconv"] },
