    "range": { minArgs: 3, maxArgs: 3, signature: "range(start, stop, step)", forms: [["start", "stop", "step"]], description: "creates a range of values between start (inclusive) and stop (exclusive) using step. Use linspace if you want value count.", details: "", params: {"start": "first value", "stop": "end of the range (not included)", "step": "distance between consecutive values"}, aliases: [] },
    "linspace": { minArgs: 3, maxArgs: 3, signature: "linspace(start, stop, count)", forms: [["start", "stop", "count"]], description: "creates count evenly spaced values from start to stop (both included). Use range to control the step instead.", details: "", params: {"start": "first value", "stop": "last value (included)", "count": "number of values"}, aliases: [] },
