    "topk": { minArgs: 2, maxArgs: 3, signature: "topk(x, k, [dim])", forms: [["x", "k", "[dim]"]], description: "returns the k largest elements along dim. For tensors it keeps them in place; dim defaults to the last.", details: "", params: {"x": "list or tensor", "k": "number of elements to keep", "dim": "dimension to select along (default: last)"}, aliases: [] },
