    "pinv": { minArgs: 1, maxArgs: 1, signature: "pinv(permutation)", forms: [["permutation"]], description: "computes the inverse permutation: where permutation[i] == j the result has result[j] == i. Not the matrix pseudoinverse; use inv(matrix, 1) for that", details: "", params: {"permutation": "list or tensor holding each index exactly once"}, aliases: [] },
