    "dot": { minArgs: 2, maxArgs: 2, signature: "dot(x, y)", forms: [["x", "y"]], description: "computes the dot product of x and y after flattening both to 1D. Use cross(x, y) if you need a per-vector product with the last dimension kept.", details: "", params: {"x": "first tensor; flattened before multiplying", "y": "second tensor with the same number of elements"}, aliases: [] },
