    "edge": { minArgs: 1, maxArgs: 2, signature: "edge(x, [kernel_size])", forms: [["x", "[kernel_size]"]], description: "detects edges in x with a Sobel filter. kernel_size must be odd and at least 3 (default 3).", details: "", params: {"x": "image or tensor", "kernel_size": "odd Sobel kernel size, at least 3 (default: 3)"}, aliases: [] },
    "distance_transform": { minArgs: 1, maxArgs: 2, signature: "distance_transform(mask, [threshold])", forms: [["mask", "[threshold]"]], description: "Euclidean distance in pixels from each pixel inside the mask to the nearest pixel outside it; outside pixels are 0. Use distance_transform(1 - mask) for the distance outside the mask", details: "", params: {"mask": "mask or image; values above threshold count as inside", "threshold": "inside/outside cutoff (default: 0.5)"}, aliases: [] },
