    "blur": { minArgs: 2, maxArgs: 3, signature: "blur(x, sigma, [auto_channels])", forms: [["x", "sigma", "[auto_channels]"]], description: "applies a separable Gaussian blur to x. Channels are expected last unless auto_channels is truthy", details: "", params: {"x": "image or tensor to blur", "sigma": "blur strength as the standard deviation in elements; 0 or less returns x unchanged", "auto_channels": "truthy to find the channel dimension automatically; otherwise channels must be last (default: false)"}, aliases: ["gaussian"] },
