    "topk_ind": { minArgs: 2, maxArgs: 3, signature: "topk_ind(x, k, [dim])", forms: [["x", "k", "[dim]"]], description: "returns the indices of the k largest elements along dim; without dim, returns indices into flatten(x)", details: "", params: {"x": "list or tensor", "k": "number of indices to return", "dim": "dimension to select along (default: indices into flatten(x))"}, aliases: ["topk_indices"] },
