    "overlay": { minArgs: 3, maxArgs: 5, signature: "overlay(base, overlay, offset, [opacity], [mode])", forms: [["base", "overlay", "offset", "[opacity]", "[mode]"]], description: "overlays overlay on base at offset. Opacity controls blending. It can be tensor or float. If it is tensor it should be the same shape as overlay. For tensors, mode picks a blend mode like blend()", details: "", params: {"base": "background value, list, text or tensor", "overlay": "value placed on top of base", "offset": "position of the overlay's low corner in base, one value per dimension", "opacity": "0-1 blend amount; a number or a tensor shaped like overlay (default: 1)", "mode": "blend mode name for tensors, see blend() (default: \"normal\")"}, aliases: [] },
