    "huber_loss": { minArgs: 2, maxArgs: 4, signature: "huber_loss(prediction, target, [delta], [reduction])", forms: [["prediction", "target", "[delta]", "[reduction]"]], description: "computes Huber loss; delta defaults to 1 and reduction to mean", details: "", params: {"prediction": "predicted values", "target": "expected values", "delta": "error size where the loss changes from quadratic to linear (default: 1)", "reduction": "\"mean\" (default), \"sum\", or \"none\" for element-wise values"}, aliases: [] },
