    "substring": { minArgs: 2, maxArgs: 3, signature: "substring(text, start, [length])", forms: [["text", "start", "[length]"]], description: "returns length characters of text starting at start. If length is not supplied, it returns the rest of the string", details: "", params: {"text": "source text", "start": "index of the first character", "length": "number of characters (default: the rest of the text)"}, aliases: ["substr"] },
