    "regex_search": { minArgs: 2, maxArgs: 2, signature: "regex_search(text, pattern)", forms: [["text", "pattern"]], description: "returns the index of the first match of the regular expression pattern in text, or -1 if there is none", details: "", params: {"text": "text to search in", "pattern": "Python regular expression"}, aliases: [] },
