    "dilate": { minArgs: 1, maxArgs: 2, signature: "dilate(x, [kernel_size])", forms: [["x", "[kernel_size]"]], description: "applies morphological dilation to x with a square kernel (default size 3).", details: "", params: {"x": "mask or image with values 0-1", "kernel_size": "size of the square kernel (default: 3)"}, aliases: [] },
    "erode": { minArgs: 1, maxArgs: 2, signature: "erode(x, [kernel_size])", forms: [["x", "[kernel_size]"]], description: "applies morphological erosion to x with a square kernel (default size 3).", details: "", params: {"x": "mask or image with values 0-1", "kernel_size": "size of the square kernel (default: 3)"}, aliases: [] },
    "morph_open": { minArgs: 1, maxArgs: 2, signature: "morph_open(x, [kernel_size])", forms: [["x", "[kernel_size]"]], description: "applies morphological opening (erosion then dilation) to x with a square kernel (default size 3).", details: "", params: {"x": "mask or image with values 0-1", "kernel_size": "size of the square kernel (default: 3)"}, aliases: [] },
    "morph_close": { minArgs: 1, maxArgs: 2, signature: "morph_close(x, [kernel_size])", forms: [["x", "[kernel_size]"]], description: "applies morphological closing (dilation then erosion) to x with a square kernel (default size 3).", details: "", params: {"x": "mask or image with values 0-1", "kernel_size": "size of the square kernel (default: 3)"}, aliases: [] },
    "rgb_to_oklab": { minArgs: 1, maxArgs: 3, signature: "rgb_to_oklab(rgb) / rgb_to_oklab(r, g, b)", forms: [["rgb"], ["r", "g", "b"]], description: "converts 0-1 sRGB to OKLab. With one argument its last dimension holds R, G, B; with three, the channels are stacked into the last dimension of the result", details: "", params: {"rgb": "sRGB colors (0-1) with R, G, B in the last dimension, or a 3-item list", "r": "red channel 0-1", "g": "green channel 0-1", "b": "blue channel 0-1"}, aliases: [] },
    "luminance": { minArgs: 1, maxArgs: 3, signature: "luminance(rgb) / luminance(r, g, b)", forms: [["rgb"], ["r", "g", "b"]], description: "Rec.709 luminance 0.2126 R + 0.7152 G + 0.0722 B of gamma-encoded colors. With one argument the first three entries of its last dimension are R, G, B and that dimension is removed", details: "", params: {"rgb": "colors (0-1) with R, G, B in the last dimension, or a 3-item list", "r": "red channel 0-1", "g": "green channel 0-1", "b": "blue channel 0-1"}, aliases: [] },
    "rgb_to_cielab": { minArgs: 1, maxArgs: 3, signature: "rgb_to_cielab(rgb) / rgb_to_cielab(r, g, b)", forms: [["rgb"], ["r", "g", "b"]], description: "converts 0-1 sRGB to CIELAB (D65) divided by 100, so L is 0-1. With one argument its last dimension holds R, G, B; with three, the channels are stacked into the last dimension of the result", details: "", params: {"rgb": "sRGB colors (0-1) with R, G, B in the last dimension, or a 3-item list", "r": "red channel 0-1", "g": "green channel 0-1", "b": "blue channel 0-1"}, aliases: [] },
    "oklab_to_rgb": { minArgs: 1, maxArgs: 3, signature: "oklab_to_rgb(oklab) / oklab_to_rgb(l, a, b)", forms: [["oklab"], ["l", "a", "b"]], description: "converts OKLab to 0-1 sRGB. With one argument its last dimension holds L, a, b; with three, the channels are stacked into the last dimension of the result", details: "", params: {"oklab": "OKLab colors with L, a, b in the last dimension, or a 3-item list", "l": "lightness", "a": "green-red axis", "b": "blue-yellow axis"}, aliases: [] },
    "cielab_to_rgb": { minArgs: 1, maxArgs: 3, signature: "cielab_to_rgb(cielab) / cielab_to_rgb(l, a, b)", forms: [["cielab"], ["l", "a", "b"]], description: "converts CIELAB divided by 100 (as returned by rgb_to_cielab) to 0-1 sRGB. With one argument its last dimension holds L, a, b; with three, the channels are stacked into the last dimension of the result", details: "", params: {"cielab": "CIELAB colors / 100 with L, a, b in the last dimension, or a 3-item list", "l": "lightness / 100 (0-1)", "a": "green-red axis / 100", "b": "blue-yellow axis / 100"}, aliases: [] },
    "rgb_to_hsv": { minArgs: 1, maxArgs: 4, signature: "rgb_to_hsv(rgb, [degrees]) / rgb_to_hsv(r, g, b, [degrees])", forms: [["rgb", "[degrees]"], ["r", "g", "b", "[degrees]"]], description: "converts RGB to HSV. With one color argument its last dimension holds R, G, B; with three, the channels are stacked into the last dimension of the result. If degrees is truthy, hue is 0-360 instead of 0-1", details: "", params: {"rgb": "colors (0-1) with R, G, B in the last dimension, or a 3-item list", "degrees": "truthy to use hue in 0-360 instead of 0-1", "r": "red channel 0-1", "g": "green channel 0-1", "b": "blue channel 0-1"}, aliases: [] },
    "hsv_to_rgb": { minArgs: 1, maxArgs: 4, signature: "hsv_to_rgb(hsv, [degrees]) / hsv_to_rgb(h, s, v, [degrees])", forms: [["hsv", "[degrees]"], ["h", "s", "v", "[degrees]"]], description: "converts HSV to RGB. With one color argument its last dimension holds H, S, V; with three, the channels are stacked into the last dimension of the result. If degrees is truthy, hue is read as 0-360 instead of 0-1", details: "", params: {"hsv": "colors with H, S, V in the last dimension, or a 3-item list", "degrees": "truthy to use hue in 0-360 instead of 0-1", "h": "hue 0-1 (0-360 with degrees)", "s": "saturation 0-1", "v": "value (brightness) 0-1"}, aliases: [] },
    "int_to_rgb": { minArgs: 1, maxArgs: 1, signature: "int_to_rgb(color)", forms: [["color"]], description: "unpacks 0xRRGGBB integers into 0-1 RGB colors. Tensors get R, G, B stacked in a new last dimension, lists return a list of colors and a number returns a 3-item list", details: "", params: {"color": "packed 0xRRGGBB integer, list or tensor"}, aliases: [] },
    "rgb_to_int": { minArgs: 1, maxArgs: 3, signature: "rgb_to_int(rgb) / rgb_to_int(r, g, b)", forms: [["rgb"], ["r", "g", "b"]], description: "packs 0-1 RGB components into 0xRRGGBB integers. With one argument the last dimension (or a 3-item list) holds R, G, B; with three, each argument is one channel", details: "", params: {"rgb": "colors with R, G, B (0-1) in the last dimension, or a 3-item list", "r": "red channel 0-1", "g": "green channel 0-1", "b": "blue channel 0-1"}, aliases: [] },
    "interpolate_linear": { minArgs: 2, maxArgs: 2, signature: "interpolate_linear(x, scale)", forms: [["x", "scale"]], description: "resizes x [N, C, ...] with (bi/tri)linear interpolation. A number scales every spatial dimension; a list is the target spatial size", details: "", params: {"x": "tensor shaped [N, C, ...] with 1-3 spatial dimensions", "scale": "a number scales every spatial dimension; a list gives the target spatial size"}, aliases: [] },
