    "sort": { minArgs: 1, maxArgs: 3, signature: "sort(x, [descending], [dim])", forms: [["x", "[descending]", "[dim]"]], description: "returns x sorted ascending, or descending when descending is truthy. Tensors are sorted along dim (default: last dimension); lists use Python sorting", details: "", params: {"x": "list or tensor to sort", "descending": "truthy to sort from largest to smallest (default: false)", "dim": "dimension to sort along (default: last)"}, aliases: [] },
    "argsort": { minArgs: 1, maxArgs: 3, signature: "argsort(x, [descending], [dim])", forms: [["x", "[descending]", "[dim]"]], description: "returns the indices that would sort x. descending defaults to false and dim defaults to the last dimension.", details: "", params: {"x": "list or tensor", "descending": "truthy to sort from largest to smallest (default: false)", "dim": "dimension to sort along (default: last)"}, aliases: [] },
    "argmin": { minArgs: 1, maxArgs: 3, signature: "argmin(x, [as_position], [dim])", forms: [["x", "[as_position]", "[dim]"]], description: "returns the minimum index globally or along dim; as_position returns global coordinates", details: "", params: {"x": "list or tensor to search", "as_position": "truthy to return the coordinates of the minimum instead of a flat index", "dim": "dimension to search along; cannot be combined with as_position"}, aliases: [] },
    "argmax": { minArgs: 1, maxArgs: 3, signature: "argmax(x, [as_position], [dim])", forms: [["x", "[as_position]", "[dim]"]], description: "returns the maximum index globally or along dim; as_position returns global coordinates", details: "", params: {"x": "list or tensor to search", "as_position": "truthy to return the coordinates of the maximum instead of a flat index", "dim": "dimension to search along; cannot be combined with as_position"}, aliases: [] },
    "softmax": { minArgs: 1, maxArgs: 2, signature: "softmax(x, [dim])", forms: [["x", "[dim]"]], description: "applies the softmax function to x (each slice sums to 1.0). dim defaults to the last dimension.", details: "", params: {"x": "scores (list or tensor)", "dim": "dimension whose slices sum to 1 (default: last)"}, aliases: [] },
    "softmin": { minArgs: 1, maxArgs: 2, signature: "softmin(x, [dim])", forms: [["x", "[dim]"]], description: "applies the softmin function to x (same as softmax(-x, [dim])). dim defaults to the last dimension.", details: "", params: {"x": "scores (list or tensor)", "dim": "dimension whose slices sum to 1 (default: last)"}, aliases: [] },
    "unique": { minArgs: 1, maxArgs: 1, signature: "unique(x)", forms: [["x"]], description: "returns the sorted unique elements of x (tensors are flattened first)", details: "", params: {"x": "list or tensor"}, aliases: [] },
    "flip": { minArgs: 2, maxArgs: 2, signature: "flip(x, dims)", forms: [["x", "dims"]], description: "reverses the order of elements along the specified dimensions. Text is reversed as a whole", details: "", params: {"x": "tensor, list or text", "dims": "dimension or list of dimensions to reverse"}, aliases: [] },
    "startswith": { minArgs: 2, maxArgs: 2, signature: "startswith(text, prefix)", forms: [["text", "prefix"]], description: "returns 1 if text starts with prefix, else 0", details: "", params: {"text": "text to check", "prefix": "start to look for"}, aliases: [] },
    "endswith": { minArgs: 2, maxArgs: 2, signature: "endswith(text, suffix)", forms: [["text", "suffix"]], description: "returns 1 if text ends with suffix, else 0", details: "", params: {"text": "text to check", "suffix": "ending to look for"}, aliases: [] },
    "squeeze": { minArgs: 1, maxArgs: 2, signature: "squeeze(x, [dim])", forms: [["x", "[dim]"]], description: "removes size-1 dimensions from tensor x, optionally at dim", details: "", params: {"x": "tensor", "dim": "only remove this dimension, if it has size 1"}, aliases: [] },
    "unsqueeze": { minArgs: 2, maxArgs: 2, signature: "unsqueeze(x, dim)", forms: [["x", "dim"]], description: "inserts a size-1 dimension into tensor x at dim", details: "", params: {"x": "tensor", "dim": "position of the new size-1 dimension"}, aliases: [] },
    "roll": { minArgs: 2, maxArgs: 3, signature: "roll(x, shifts, [dim])", forms: [["x", "shifts", "[dim]"]], description: "circularly shifts tensor x along dim (default 0)", details: "", params: {"x": "tensor", "shifts": "number of places to shift; elements pushed off one end come back at the other", "dim": "dimension to shift along (default: 0)"}, aliases: [] },
    "cov": { minArgs: 2, maxArgs: 2, signature: "cov(x, y)", forms: [["x", "y"]], description: "computes the sample covariance of the flattened x and y (which must have the same number of elements)", details: "", params: {"x": "first values; flattened", "y": "second values with the same number of elements"}, aliases: [] },
    "corr": { minArgs: 2, maxArgs: 2, signature: "corr(x, y)", forms: [["x", "y"]], description: "computes the Pearson correlation coefficient between x and y", details: "", params: {"x": "first values", "y": "second values"}, aliases: ["correlation"] },
    "correlation": { minArgs: 2, maxArgs: 2, signature: "correlation(x, y)", forms: [["x", "y"]], description: "computes the Pearson correlation coefficient between x and y", details: "", params: {"x": "first values", "y": "second values"}, aliases: ["corr"] },
    "entropy": { minArgs: 1, maxArgs: 1, signature: "entropy(logits)", forms: [["logits"]], description: "computes the Shannon entropy (in nats) of softmax(logits) over all elements", details: "", params: {"logits": "scores (list or tensor)"}, aliases: [] },
    "crop": { minArgs: 3, maxArgs: 3, signature: "crop(x, start, size)", forms: [["x", "start", "size"]], description: "crops the region of x beginning at start (the low corner). The result always has shape size; parts outside x are zero-filled. On text, returns at most size characters", details: "", params: {"x": "tensor or text", "start": "low corner of the region, one index per dimension", "size": "size of the result, one value per dimension"}, aliases: [] },
    "coords": { minArgs: 2, maxArgs: 3, signature: "coords(shape, dim, [dtype_template])", forms: [["shape", "dim", "[dtype_template]"]], description: "generates a tensor with the specified shape whose values are the coordinates of each element along dim. An optional tensor supplies the output dtype (default float32).", details: "", params: {"shape": "list of dimension sizes", "dim": "dimension whose index becomes the value", "dtype_template": "tensor whose dtype the result uses (default: float32)"}, aliases: ["coordinates"] },
